(6277375, 927745, 53572, '<td valign="top"><a href="//www.dpchallenge.com/image.php?IMAGE_ID=657241" rel="nofollow" target="_blank"><img alt="'' . substr(''//images.dpchallenge.com/images_portfolio/50000-54999/53572/120/Copyrighted_Image_Reuse_Prohibited_657241.jpg'', strrpos(''//images.dpchallenge.com/images_portfolio/50000-54999/53572/120/Copyrighted_Image_Reuse_Prohibited_657241.jpg'', ''/'') + 1) . ''" border="0" src="//images.dpchallenge.com/images_portfolio/50000-54999/53572/120/Copyrighted_Image_Reuse_Prohibited_657241.jpg"/></a> A burst of light, an explosion of phoenix flight, flying from in darkness to enrichen  us all.</td>', ' A burst of light, an explosion of phoenix flight, flying from in darkness to enrichen  us all.', '2011-01-09 12:59:00.000000', NULL, 0),
(6277381, 927632, 53572, '<td valign="top"><a href="//www.dpchallenge.com/image.php?IMAGE_ID=657243" rel="nofollow" target="_blank"><img alt="'' . substr(''//images.dpchallenge.com/images_portfolio/50000-54999/53572/120/Copyrighted_Image_Reuse_Prohibited_657243.jpg'', strrpos(''//images.dpchallenge.com/images_portfolio/50000-54999/53572/120/Copyrighted_Image_Reuse_Prohibited_657243.jpg'', ''/'') + 1) . ''" border="0" src="//images.dpchallenge.com/images_portfolio/50000-54999/53572/120/Copyrighted_Image_Reuse_Prohibited_657243.jpg"/></a> Starship flights, galactic birds brush their feathers across our souls.  Lovely work.</td>', ' Starship flights, galactic birds brush their feathers across our souls.  Lovely work.', '2011-01-09 13:06:39.000000', NULL, 0),
(6277386, 927750, 53572, '<td valign="top"><a href="//www.dpchallenge.com/image.php?IMAGE_ID=657242" rel="nofollow" target="_blank"><img alt="'' . substr(''//images.dpchallenge.com/images_portfolio/50000-54999/53572/120/Copyrighted_Image_Reuse_Prohibited_657242.jpg'', strrpos(''//images.dpchallenge.com/images_portfolio/50000-54999/53572/120/Copyrighted_Image_Reuse_Prohibited_657242.jpg'', ''/'') + 1) . ''" border="0" src="//images.dpchallenge.com/images_portfolio/50000-54999/53572/120/Copyrighted_Image_Reuse_Prohibited_657242.jpg"/></a> Fire, or dandelion head, the smoke ends trail though our consciousness.  Lovely and soft, and explosion of fuzziness.</td>', ' Fire, or dandelion head, the smoke ends trail though our consciousness.  Lovely and soft, and explosion of fuzziness.', '2011-01-09 13:08:39.000000', NULL, 0),
(6277394, 927632, 60495, '<td valign="top">This is a stunning image, I gave it a nine and it was one of my favorites in the challenge. I just loved the sense of movement, almost like a shooting star.</td>', 'This is a stunning image, I gave it a nine and it was one of my favorites in the challenge. I just loved the sense of movement, almost like a shooting star.', '2011-01-09 13:13:56.000000', NULL, 0),
(6277398, 927725, 15711, '<td valign="top">Yay, Rob.  I didn''t vote on this one, but looking at them, you deserve your blue. Congrats.</td>', 'Yay, Rob.  I didn''t vote on this one, but looking at them, you deserve your blue. Congrats.', '2011-01-09 13:22:59.000000', NULL, 0),
(6277399, 927718, 15711, '<td valign="top">I love that the "works" look like rounded feather clusters!!  Fabulous city scape.</td>', 'I love that the "works" look like rounded feather clusters!!  Fabulous city scape.', '2011-01-09 13:23:22.000000', NULL, 0),
(6277406, 927718, 100831, '<td valign="top">Exquisite - and beautifully balanced. Congratulations on your ribbon!!</td>', 'Exquisite - and beautifully balanced. Congratulations on your ribbon!!', '2011-01-09 13:37:08.000000', NULL, 0),
(6277411, 927718, 124703, '<td valign="top">Well deserved ribbon, my favorite photo of the challenge.</td>', 'Well deserved ribbon, my favorite photo of the challenge.', '2011-01-09 13:41:28.000000', NULL, 0),
(6277450, 927718, 112739, '<td valign="top">I have this as the winner in my book. Most excellent work, has a huge "Ooo and Ahh" presence! Congrats on your ribbon.</td>', 'I have this as the winner in my book. Most excellent work, has a huge "Ooo and Ahh" presence! Congrats on your ribbon.', '2011-01-09 14:17:41.000000', NULL, 0),
(6277470, 927413, 93714, '<td valign="top"><u>It looks like 1st. place to me.</u>  It''s an amazing capture with perfect control of exposure and lens speed... an absolutely gorgeous image!</td>', 'It looks like 1st. place to me.  It''s an amazing capture with perfect control of exposure and lens speed... an absolutely gorgeous image!', '2011-01-09 14:51:20.000000', NULL, 0),
(6277481, 927553, 92577, '<td valign="top">On the map with a bang! Congratulations!</td>', 'On the map with a bang! Congratulations!', '2011-01-09 15:08:26.000000', NULL, 0),
(6277488, 927718, 92577, '<td valign="top">good to see you back among the ribbons</td>', 'good to see you back among the ribbons', '2011-01-09 15:13:33.000000', NULL, 0),
(6277512, 927734, 50695, '<td valign="top">you put a lot of work into this! thanks to your cone you achieved the iconic fireworks shape, but with a different direction... which I believe you allude to in your title.</td>', 'you put a lot of work into this! thanks to your cone you achieved the iconic fireworks shape, but with a different direction... which I believe you allude to in your title.', '2011-01-09 15:31:01.000000', NULL, 0),
(6277515, 927720, 50695, '<td valign="top">I think this photo demonstrates an equivalence between confetti and fireworks. Not only do they have the same function, celebration, but your photo shows they have a similar flirtatious relationship with gravity. You also capture the symbolism of brightness.</td>', 'I think this photo demonstrates an equivalence between confetti and fireworks. Not only do they have the same function, celebration, but your photo shows they have a similar flirtatious relationship with gravity. You also capture the symbolism of brightness.', '2011-01-09 15:33:37.000000', NULL, 0),
(6277533, 927553, 68586, '<td valign="top">Very nice shot !</td>', 'Very nice shot !', '2011-01-09 15:41:51.000000', NULL, 0),
(6277561, 927734, 11854, '<td valign="top">I quite liked this!</td>', 'I quite liked this!', '2011-01-09 16:23:41.000000', NULL, 0),
(6277573, 927745, 66384, '<td valign="top">Makes me think of a moth and flame.</td>', 'Makes me think of a moth and flame.', '2011-01-09 16:40:08.000000', NULL, 0),
(6277576, 927750, 66384, '<td valign="top">The sun is the ultimate firework, and I love the effect you achieved with this filter.</td>', 'The sun is the ultimate firework, and I love the effect you achieved with this filter.', '2011-01-09 16:42:08.000000', NULL, 0),
(6277586, 927734, 66384, '<td valign="top">Ha, I thought this was camera shake. OOPS. The black ''sky'' makes this look very real.</td>', 'Ha, I thought this was camera shake. OOPS. The black ''sky'' makes this look very real.', '2011-01-09 16:47:16.000000', NULL, 0),
(6277590, 927720, 66384, '<td valign="top">I gave it a 7. I like the OOB approach. I knew it wasn''t fireworks, but it is still celebratory in the spirit of fireworks. :) Sorry I spoiled your brown ribbon.</td>', 'I gave it a 7. I like the OOB approach. I knew it wasn''t fireworks, but it is still celebratory in the spirit of fireworks. :) Sorry I spoiled your brown ribbon.', '2011-01-09 16:49:41.000000', NULL, 0),
(6277599, 927413, 59029, '<td valign="top">This is precisely the kind of thing of image I want to see on the home page.  Not just fireworks in the sky and illuminating surrounding buildings, but one step further and get the reflections of the fireworks in any available water.  Great work and congrats.</td>', 'This is precisely the kind of thing of image I want to see on the home page.  Not just fireworks in the sky and illuminating surrounding buildings, but one step further and get the reflections of the fireworks in any available water.  Great work and congrats.', '2011-01-09 17:09:07.000000', NULL, 0),
(6277621, 927515, 22301, '<td valign="top">Your ribbon is coming, it will be sweet. :) Nice timing to get the whole building a blaze.</td>', 'Your ribbon is coming, it will be sweet. :) Nice timing to get the whole building a blaze.', '2011-01-09 17:44:18.000000', NULL, 0),
