(6277705, 927473, 68769, '<td valign="top">At Wall-mart you will never see great art, you will never see this at Wall-mart..</td>', 'At Wall-mart you will never see great art, you will never see this at Wall-mart..', '2011-01-09 18:57:55.000000', NULL, 0),
