INSERT INTO comments ("id", "image_id", "commenter_id", "raw_comment", "comment", "date", "edited", "made_during_challenge") VALUES
(6281204, 927718, 72929, '<td valign="top">Had I voted in this challenge, I would''ve given this a 10 and rated it my favorite submission. I especially like the idea/trick of covering the lens for the initial burst... thanks for the tip! I will try it next time I shoot fireworks.</td>', 'Had I voted in this challenge, I would''ve given this a 10 and rated it my favorite submission. I especially like the idea/trick of covering the lens for the initial burst... thanks for the tip! I will try it next time I shoot fireworks.', '2011-01-12 10:47:22.000000', NULL, 0),
(6281292, 927619, 77991, '<td valign="top">Thanks everyone for the great comments!   I really appreciate it.   I was happy with the image considering this was just some backyard fireworks launched from the backyard and I was not prepared to even shoot this (no tripod or remote switch).<br/><br/><i>Message edited by author 2011-01-12 11:41:53.</i></td>', 'Thanks everyone for the great comments!   I really appreciate it.   I was happy with the image considering this was just some backyard fireworks launched from the backyard and I was not prepared to even shoot this (no tripod or remote switch).', '2011-01-12 11:41:11.000000', '2011-01-12 11:41:53.000000', 0),
(6281341, 927413, 96751, '<td valign="top">Aw nuts!  This has happened a LOT recently, to first timers who don''t realize the importance of that original.  But you''re off to a great start, so DON''T stop submitting, please!!!</td>', 'Aw nuts!  This has happened a LOT recently, to first timers who don''t realize the importance of that original.  But you''re off to a great start, so DON''T stop submitting, please!!!', '2011-01-12 12:33:02.000000', NULL, 0),
(6281347, 927553, 96751, '<td valign="top">LOVE all those dancing sparks.  Congrats on your new ribbon!!</td>', 'LOVE all those dancing sparks.  Congrats on your new ribbon!!', '2011-01-12 12:35:30.000000', NULL, 0),
(6281350, 927515, 96751, '<td valign="top">I have a dress that does that when I move :-)<br/> <br/>Awesome capture!</td>', 'I have a dress that does that when I move :-) Awesome capture!', '2011-01-12 12:36:20.000000', NULL, 0),
(6281600, 927553, 19825, '<td valign="top">I am glad this got bumped up to a ribbon, I was initially surprised it did not ribbon. This was my clear favorite of the challenge. I love it''s drama and composition.</td>', 'I am glad this got bumped up to a ribbon, I was initially surprised it did not ribbon. This was my clear favorite of the challenge. I love it''s drama and composition.', '2011-01-12 15:49:50.000000', NULL, 0),
